package dev.aeon.ui.platform

import dev.aeon.ui.api.fromBase64
import dev.aeon.ui.api.toBase64
import kotlinx.coroutines.await
import kotlin.js.JsAny
import kotlin.js.JsString
import kotlin.js.Promise
import kotlin.js.toJsString

/**
 * Browser implementation. The ECDSA P-256 private key is generated by WebCrypto as NON-EXTRACTABLE and kept in
 * IndexedDB as an opaque CryptoKey: page scripts can ask it to sign but can never read the key material.
 * WebCrypto is available only in secure contexts (https, or http://localhost / 127.0.0.1); on a plain-HTTP LAN
 * address the browser hides `crypto.subtle`, and this app reports that instead of pretending to work.
 * All values cross the Kotlin/JS boundary as base64 strings.
 */
private fun installHelpers(): Unit = js(
    """{
  if (!window.__aeon) {
    const b64 = (u8) => { let s = ''; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000)); return btoa(s); };
    const unb64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
    const need = () => { if (!window.crypto || !window.crypto.subtle) throw new Error('This page is not a secure context, so the browser blocks WebCrypto. Open Aeon via http://127.0.0.1 or https.'); return window.crypto.subtle; };
    const idb = () => new Promise((res, rej) => { const r = indexedDB.open('aeon-ui', 1); r.onupgradeneeded = () => r.result.createObjectStore('keys'); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
    const idbOp = async (mode, fn) => { const db = await idb(); return new Promise((res, rej) => { const q = fn(db.transaction('keys', mode).objectStore('keys')); q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error); }); };
    const pair = async () => {
      let p = await idbOp('readonly', (s) => s.get('device'));
      if (!p) {
        p = await need().generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign', 'verify']);
        await idbOp('readwrite', (s) => s.put(p, 'device'));
      }
      return p;
    };
    window.__aeon = {
      publicKey: async () => b64(new Uint8Array(await need().exportKey('spki', (await pair()).publicKey))),
      sign: async (data) => b64(new Uint8Array(await need().sign({ name: 'ECDSA', hash: 'SHA-256' }, (await pair()).privateKey, unb64(data)))),
      sha256: async (data) => b64(new Uint8Array(await need().digest('SHA-256', unb64(data)))),
      hmac: async (key, msg) => { const k = await need().importKey('raw', unb64(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']); return b64(new Uint8Array(await need().sign('HMAC', k, unb64(msg)))); },
      random: async (n) => b64(window.crypto.getRandomValues(new Uint8Array(n))),
      reset: async () => { await idbOp('readwrite', (s) => s.delete('device')); return ''; },
    };
  }
}""",
)

private fun jsPublicKey(): Promise<JsString> = js("window.__aeon.publicKey()")
private fun jsSign(data: String): Promise<JsString> = js("window.__aeon.sign(data)")
private fun jsSha256(data: String): Promise<JsString> = js("window.__aeon.sha256(data)")
private fun jsHmac(key: String, msg: String): Promise<JsString> = js("window.__aeon.hmac(key, msg)")
private fun jsRandom(n: Int): Promise<JsString> = js("window.__aeon.random(n)")
private fun jsReset(): Promise<JsString> = js("window.__aeon.reset()")

private suspend fun Promise<JsString>.str(): String = await<JsString>().toString()

class WebDeviceCrypto : DeviceCrypto {
    init {
        installHelpers()
    }

    override suspend fun publicKeyB64(): String = jsPublicKey().str()
    override suspend fun sign(data: ByteArray): String = jsSign(data.toBase64()).str()
    override suspend fun sha256(data: ByteArray): ByteArray = jsSha256(data.toBase64()).str().fromBase64()
    override suspend fun hmacSha256(key: ByteArray, message: ByteArray): ByteArray = jsHmac(key.toBase64(), message.toBase64()).str().fromBase64()
    override suspend fun randomBytes(count: Int): ByteArray = jsRandom(count).str().fromBase64()
    override suspend fun reset() {
        jsReset().str()
    }
}

private fun jsGetItem(key: String): JsString? = js("window.localStorage.getItem(key)")
private fun jsSetItem(key: String, value: String): Unit = js("window.localStorage.setItem(key, value)")
private fun jsRemoveItem(key: String): Unit = js("window.localStorage.removeItem(key)")
private fun jsNow(): Double = js("Date.now()")
// Numeric ISO-like format on purpose: locale strings can contain CJK/AM-PM words that the default Compose font cannot draw.
private fun jsFormat(ms: Double): String = js("(function(d){var p=function(n){return String(n).padStart(2,'0')};return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds())})(new Date(ms))")
private fun jsOrigin(): String = js("window.location.origin")

/** Non-secret client state only (server address, device id). localStorage may be unavailable; failures are tolerated. */
class WebKeyValueStore : KeyValueStore {
    override fun get(key: String): String? = runCatching { jsGetItem("aeon.$key")?.toString() }.getOrNull()
    override fun put(key: String, value: String) {
        runCatching { jsSetItem("aeon.$key", value) }
    }
    override fun remove(key: String) {
        runCatching { jsRemoveItem("aeon.$key") }
    }
}

actual fun createDeviceCrypto(): DeviceCrypto = WebDeviceCrypto()

actual fun createKeyValueStore(): KeyValueStore = WebKeyValueStore()

actual fun nowMillis(): Long = jsNow().toLong()

actual fun defaultDeviceName(): String = "Web browser"

actual fun formatDateTime(millis: Long): String = jsFormat(millis.toDouble())

/** The address this page was loaded from: when Aeon serves the UI, that is the API address too. */
fun pageOrigin(): String = jsOrigin()

@Suppress("unused")
private fun unusedJsAny(x: JsAny) = x
@Suppress("unused")
private fun unusedToJsString(s: String) = s.toJsString()
